const ACCESS_ALLOWED_ACE_TYPE: u8 = 0;
const ACCESS_DENIED_ACE_TYPE: u8 = 1;
const INHERIT_ONLY_ACE: u8 = 0x08;

/// Access mode for a private state child.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PrivateFileAccess {
    /// Open an existing child for reads.
    Read,
    /// Open an existing child for reads and writes without recreating missing state.
    Write,
    /// Open or create a child for retained-owner reads and writes.
    Create,
}

/// Creates or opens a retained private-state directory.
pub fn open_private_state_directory(root: &Path) -> io::Result<File> {
    let directory = directory::open(root)?;
    validate_handle(&directory, HandleKind::Directory)?;
    Ok(directory)
}

/// Creates one new retained private-state directory with its private descriptor.
///
/// An occupied leaf returns `AlreadyExists`; existing state is never adopted,
/// re-owned, or re-permissioned. Acquisition rejects reparse traversal before
/// creating the leaf and validates the exact returned handle.
pub fn create_new_private_state_directory(root: &Path) -> io::Result<File> {
    let directory = directory::create_new(root)?;
    validate_handle(&directory, HandleKind::Directory)?;
    Ok(directory)
}

/// Opens one normal-name child relative to the retained private directory.
pub fn open_private_state_child(
    directory: &File,
    name: &str,
    access: PrivateFileAccess,
) -> io::Result<File> {
    let path = child_path(directory, name)?;
    let file = match access {
        PrivateFileAccess::Create => {
            let wide = wide_path(&path)?;
            with_private_security(|security| {
                let handle = unsafe {
                    CreateFileW(
                        wide.as_ptr(),
                        FILE_GENERIC_READ | FILE_GENERIC_WRITE,
                        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                        security,
                        CREATE_NEW,
                        FILE_FLAG_OPEN_REPARSE_POINT,
                        /*htemplatefile*/ 0,
                    )
                };
                if handle != INVALID_HANDLE_VALUE {
                    // Transfer the newly created, non-inheritable handle to File.
                    return Ok(unsafe { File::from_raw_handle(handle as *mut c_void) });
                }
                let error = io::Error::last_os_error();
                if error.kind() != io::ErrorKind::AlreadyExists {
                    return Err(error);
                }
                // Existing state is never repaired, re-owned, or re-permissioned.
                OpenOptions::new()
                    .read(true)
                    .write(true)
                    .custom_flags(FILE_FLAG_OPEN_REPARSE_POINT)
                    .open(&path)
            })?
        }
        PrivateFileAccess::Read | PrivateFileAccess::Write => OpenOptions::new()
            .read(true)
            .write(access == PrivateFileAccess::Write)
            .custom_flags(FILE_FLAG_OPEN_REPARSE_POINT)
            .open(&path)?,
    };
    validate_handle(&file, HandleKind::File)?;
    let opened = final_path(&file)?;
    if opened.parent() != path.parent() || opened.file_name() != path.file_name() {
        return Err(unsafe_state("private child escaped its retained directory"));
    }
    Ok(file)
}

/// Checks for one valid private child without following a redirect.
pub fn private_state_child_exists(directory: &File, name: &str) -> io::Result<bool> {
    let path = child_path(directory, name)?;
    let mut options = OpenOptions::new();
    options
        .read(true)
        .custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
    match options.open(path) {
        Ok(file) => {
            validate_handle(&file, HandleKind::File)?;
            Ok(true)
        }
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(error),
    }
}

/// Atomically and durably replaces one validated private child with another.
pub fn replace_private_state_child(
    directory: &File,
    source_name: &str,
    destination_name: &str,
) -> io::Result<()> {
    let source = child_path(directory, source_name)?;
    let destination = child_path(directory, destination_name)?;
    validate_handle(
        &OpenOptions::new()
            .read(true)
            .custom_flags(FILE_FLAG_OPEN_REPARSE_POINT)
            .open(&source)?,
        HandleKind::File,
    )?;
    if private_state_child_exists(directory, destination_name)? {
        validate_handle(
            &OpenOptions::new()
                .read(true)
                .custom_flags(FILE_FLAG_OPEN_REPARSE_POINT)
                .open(&destination)?,
            HandleKind::File,
        )?;
    }
    let source = wide_path(&source)?;
    let destination = wide_path(&destination)?;
    let replaced = unsafe {
        MoveFileExW(
            source.as_ptr(),
            destination.as_ptr(),
            MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH,
        )
    };
    if replaced == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

#[derive(Clone, Copy)]
enum HandleKind {
    Directory,
    File,
}

fn validate_handle(file: &File, kind: HandleKind) -> io::Result<()> {
    let information = winapi_util::file::information(file)?;
    let attributes = information.file_attributes();
    let is_directory = attributes & u64::from(FILE_ATTRIBUTE_DIRECTORY) != 0;
    if attributes & u64::from(FILE_ATTRIBUTE_REPARSE_POINT) != 0
        || is_directory != matches!(kind, HandleKind::Directory)
        || matches!(kind, HandleKind::File) && information.number_of_links() != 1
    {
        return Err(unsafe_state("private state handle type is unsafe"));
    }
    validate_private_owner_and_dacl(file)
}

fn validate_private_owner_and_dacl(file: &File) -> io::Result<()> {
    let current_user = CurrentUser::read()?;
    let mut owner = ptr::null_mut();
    let mut dacl: *mut ACL = ptr::null_mut();
    let mut descriptor = ptr::null_mut();
    let status = unsafe {
        GetSecurityInfo(
            file.as_raw_handle() as HANDLE,
            1, // SE_FILE_OBJECT
            OWNER_SECURITY_INFORMATION | DACL_SECURITY_INFORMATION,
            &mut owner,
            ptr::null_mut(),
            &mut dacl,
            ptr::null_mut(),
            &mut descriptor,
        )
    };
    if status != ERROR_SUCCESS || descriptor.is_null() || owner.is_null() || dacl.is_null() {
        if !descriptor.is_null() {
            unsafe { LocalFree(descriptor as HLOCAL) };
        }
        return Err(unsafe_state(
            "private state security descriptor is incomplete",
        ));
    }
    let valid = unsafe {
        EqualSid(owner, current_user.sid()) != 0
            && !dacl_grants_untrusted_access(dacl, current_user.sid())
    };
    unsafe { LocalFree(descriptor as HLOCAL) };
    if !valid {
        return Err(unsafe_state("private state owner or DACL is unsafe"));
    }
    Ok(())
}

unsafe fn dacl_grants_untrusted_access(dacl: *mut ACL, current_user: *mut c_void) -> bool {
    if dacl.is_null() || unsafe { IsValidAcl(dacl) } == 0 {
        return true;
    }
    let mut information: ACL_SIZE_INFORMATION = unsafe { std::mem::zeroed() };
    if unsafe {
        GetAclInformation(
            dacl as *const ACL,
            (&mut information as *mut ACL_SIZE_INFORMATION).cast(),
            std::mem::size_of::<ACL_SIZE_INFORMATION>() as u32,
            AclSizeInformation,
        )
    } == 0
    {
        return true;
    }
    // GetAclInformation authenticates the number of in-use ACL bytes. Use
    // that returned span to validate every GetAce pointer before dereferencing
    // the ACE header, SID count or allow-mask. Never trust AceSize alone.
    let acl_start = dacl as usize;
    let acl_bytes_in_use = information.AclBytesInUse as usize;
    let mapping = GENERIC_MAPPING {
        GenericRead: FILE_GENERIC_READ,
        GenericWrite: FILE_GENERIC_WRITE,
        GenericExecute: FILE_GENERIC_EXECUTE,
        GenericAll: u32::MAX,
    };
    let access_mask = FILE_GENERIC_READ
        | FILE_GENERIC_WRITE
        | FILE_GENERIC_EXECUTE
        | FILE_WRITE_DATA
        | FILE_APPEND_DATA
        | FILE_WRITE_EA
        | FILE_WRITE_ATTRIBUTES
        | FILE_DELETE_CHILD
        | DELETE
        | WRITE_DAC
        | WRITE_OWNER;
    for index in 0..information.AceCount {
        let mut ace = ptr::null_mut();
        if unsafe { GetAce(dacl as *const ACL, index, &mut ace) } == 0 || ace.is_null() {
            // A failed lookup or null ACE must never reach a raw dereference.
            return true;
        }
        if !ace_span_fits_acl(
            acl_start,
            acl_bytes_in_use,
            ace as usize,
            std::mem::size_of::<ACE_HEADER>(),
        ) {
            return true;
        }
        let header = unsafe { ptr::read_unaligned(ace.cast::<ACE_HEADER>()) };
        let ace_size = usize::from(header.AceSize);
        if ace_size < std::mem::size_of::<ACCESS_ALLOWED_ACE>()
            || !ace_span_fits_acl(acl_start, acl_bytes_in_use, ace as usize, ace_size)
        {
            return true;
        }
        if header.AceType == ACCESS_DENIED_ACE_TYPE || header.AceFlags & INHERIT_ONLY_ACE != 0 {
            continue;
        }
        if header.AceType != ACCESS_ALLOWED_ACE_TYPE {
            return true;
        }
        // Validate the complete SID lies within the ACE before Win32 reads it.
        let sid_offset = std::mem::offset_of!(ACCESS_ALLOWED_ACE, SidStart);
        if !sid_length_fits_ace(usize::from(header.AceSize), 0) {
            return true;
        }
        let sid = unsafe { ace.cast::<u8>().add(sid_offset) }.cast::<c_void>();
        let sub_authority_count = unsafe { *sid.cast::<u8>().add(1) };
        if !sid_length_fits_ace(usize::from(header.AceSize), sub_authority_count)
            || unsafe { IsValidSid(sid) } == 0
        {
            return true;
        }
        // The fixed-size ACE fields are now within the validated allocation.
        // Avoid producing a reference to a possibly unaligned Win32 buffer.
        let allowed = unsafe { ptr::read_unaligned(ace.cast::<ACCESS_ALLOWED_ACE>()) };
        let mut mask = allowed.Mask;
        unsafe { MapGenericMask(&mut mask, &mapping) };
        if mask & access_mask != 0 && !unsafe { trusted_access_sid(sid, current_user) } {
            return true;
        }
    }
    false
}

/// Validate an ACE pointer and its requested span using the ACL byte count
/// returned by Win32, without dereferencing any untrusted ACE pointer first.
///
/// The caller owns a live ACL from GetSecurityInfo (or a test fixture),
/// validated by IsValidAcl and GetAclInformation. Integer overflow and ACE
/// pointers before the first ACE or into unused ACL capacity fail closed.
fn ace_span_fits_acl(
    acl_start: usize,
    acl_bytes_in_use: usize,
    ace_start: usize,
    span: usize,
) -> bool {
    if span < std::mem::size_of::<ACE_HEADER>() {
        return false;
    }
    let Some(first_ace) = acl_start.checked_add(std::mem::size_of::<ACL>()) else {
        return false;
    };
    let Some(acl_end) = acl_start.checked_add(acl_bytes_in_use) else {
        return false;
    };
    let Some(ace_end) = ace_start.checked_add(span) else {
        return false;
    };
    ace_start >= first_ace && ace_end <= acl_end
}

/// Check that a SID header and all sub-authorities fit inside the ACE.
fn sid_length_fits_ace(ace_size: usize, sub_authority_count: u8) -> bool {
    let Some(sid_bytes) = ace_size.checked_sub(std::mem::offset_of!(ACCESS_ALLOWED_ACE, SidStart))
    else {
        return false;
    };
    let required_bytes = 8 + usize::from(sub_authority_count) * 4;
    sid_bytes >= required_bytes
}

unsafe fn trusted_access_sid(sid: *mut c_void, current_user: *mut c_void) -> bool {
    unsafe {
        EqualSid(sid, current_user) != 0
            || IsWellKnownSid(sid, WinLocalSystemSid) != 0
            || IsWellKnownSid(sid, WinBuiltinAdministratorsSid) != 0
            || IsWellKnownSid(sid, WinCreatorOwnerSid) != 0
    }
}

fn child_path(directory: &File, name: &str) -> io::Result<PathBuf> {
    let path = Path::new(name);
    let mut components = path.components();
    if !matches!(components.next(), Some(Component::Normal(_))) || components.next().is_some() {
        return Err(unsafe_state("private child name is not a normal component"));
    }
    Ok(final_path(directory)?.join(path))
}

fn final_path(file: &File) -> io::Result<PathBuf> {
    let handle = file.as_raw_handle() as HANDLE;
    let length = unsafe { GetFinalPathNameByHandleW(handle, ptr::null_mut(), 0, 0) };
    if length == 0 {
        return Err(io::Error::last_os_error());
    }
    let mut buffer = vec![0_u16; length as usize + 1];
    let written =
        unsafe { GetFinalPathNameByHandleW(handle, buffer.as_mut_ptr(), buffer.len() as u32, 0) };
    if written == 0 || written as usize >= buffer.len() {
        return Err(io::Error::last_os_error());
    }
    Ok(std::ffi::OsString::from_wide(&buffer[..written as usize]).into())
}

fn wide_path(path: &Path) -> io::Result<Vec<u16>> {
    use std::os::windows::ffi::OsStrExt;

    if path.as_os_str().encode_wide().any(|unit| unit == 0) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "path contains NUL",
        ));
    }
    let absolute = std::path::absolute(path)?;
    let mut wide: Vec<u16> = absolute.as_os_str().encode_wide().collect();
    // Preserve Rust filesystem support for long paths when using Win32 directly.
    if !wide.starts_with(&[92, 92, 63, 92]) {
        let prefix = if wide.starts_with(&[92, 92]) {
            wide.drain(..2);
            r"\\?\UNC\"
        } else {
            r"\\?\"
        };
        wide.splice(..0, prefix.encode_utf16());
    }
    wide.push(0);
    Ok(wide)
}

fn unsafe_state(message: &'static str) -> io::Error {
    io::Error::new(io::ErrorKind::PermissionDenied, message)
}

struct CurrentUser {
    token: HANDLE,
    buffer: Vec<u8>,
}

impl CurrentUser {
    fn read() -> io::Result<Self> {
        let mut token = 0;
        if unsafe { OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &mut token) } == 0 {
            return Err(io::Error::last_os_error());
        }
        let mut length = 0;
        unsafe {
            GetTokenInformation(token, TokenUser, ptr::null_mut(), 0, &mut length);
        }
        if length == 0 {
            unsafe { CloseHandle(token) };
            return Err(io::Error::last_os_error());
        }
        let mut buffer = vec![0_u8; length as usize];
        let ok = unsafe {
            GetTokenInformation(
                token,
                TokenUser,
                buffer.as_mut_ptr().cast(),
                length,
                &mut length,
            )
        };
        if ok == 0 {
            unsafe { CloseHandle(token) };
            return Err(io::Error::last_os_error());
        }
        Ok(Self { token, buffer })
    }

    fn sid(&self) -> *mut c_void {
        let user = unsafe { ptr::read_unaligned(self.buffer.as_ptr() as *const TOKEN_USER) };
        user.User.Sid
    }
}

impl Drop for CurrentUser {
    fn drop(&mut self) {
        if self.token != 0 {
            unsafe { CloseHandle(self.token) };
        }
    }
}

